94	                .andExpect(jsonPath("$.status").value("ACTIVE"))
95	                .andExpect(jsonPath("$.monitorRound").value(1))
96	                .andExpect(jsonPath("$.roundFailed").value(1))
97	                .andExpect(jsonPath("$.roundSuccess").value(0));
98	
