100	        receipt(t2, "r-rc2", "SUCCESS");
101	        mockMvc.perform(get("/api/releases/" + releaseId + "/monitor"))
102	                .andExpect(jsonPath("$.status").value("ACTIVE"))
103	                .andExpect(jsonPath("$.roundFailed").value(1))
104	                .andExpect(jsonPath("$.roundSuccess").value(1));
