132	        String pausedAt = com.jayway.jsonpath.JsonPath.read(
133	                mockMvc.perform(get("/api/releases/" + releaseId + "/history")).andReturn()
134	                        .getResponse().getContentAsString(), "$.pauses[0].pausedAtUtc");
